import numpy as np
from decimal import Decimal, getcontext, InvalidOperation

def solve(payload):
    """
    Compute combined uncertainty across multiple components
    with optional correlation and scaling factors.

    Args:
        payload: A dictionary containing:
            - components: List of component dictionaries.
            - correlation_matrix: Optional numpy-like 2D array for inter-component correlation.
            - coverage_factor: Optional scalar value to scale the final uncertainty.

    Returns:
        A dictionary with:
        - valid: Boolean indicating if the computation was valid.
        - uncertainty: Combined uncertainty (float).
        - components: List of component details (sensitivity and uncertainty).
    """

    components = payload.get("components", [])
    correlation_matrix = payload.get("correlation_matrix")
    coverage_factor = payload.get("coverage_factor")

    # Validate components
    if not components:
        return {"valid": False, "reason": "unsupported_component_count"}

    n = len(components)
    sensitivities = []
    u_i_list = []

    for comp in components:
        if "type" not in comp:
            return {"valid": False, "reason": "invalid_component_kind"}

        if "sensitivity" not in comp:
            return {"valid": False, "reason": "invalid_component_kind"}

        try:
            sensitivity = Decimal(str(comp["sensitivity"]))
        except:
            return {"valid": False, "reason": "invalid_sensitivity"}

        if comp["type"] == "type_a":
            if "observations" not in comp:
                return {"valid": False, "reason": "missing_required_field_for_type_a"}

            try:
                obs = [Decimal(str(x)) for x in comp["observations"]]
            except:
                return {"valid": False, "reason": "invalid_observations_data_type"}

            if len(obs) < 2:
                return {"valid": False, "reason": "insufficient_observations_for_type_a"}

            mean = sum(obs) / Decimal(len(obs))
            variance = sum((x - mean) ** 2 for x in obs) / Decimal(len(obs) - 1)
            std = variance ** Decimal(0.5)
            u_i = std / Decimal(len(obs)) ** Decimal(0.5)
            u_i_list.append(u_i)
        elif comp["type"] == "type_b_rectangular":
            if "half_width" not in comp:
                return {"valid": False, "reason": "missing_required_field_for_type_b"}

            half_width = Decimal(str(comp["half_width"]))
            if half_width < 0:
                return {"valid": False, "reason": "negative_half_width"}
            u_i = half_width / Decimal(3) ** Decimal(0.5)
            u_i_list.append(u_i)
        else:
            return {"valid": False, "reason": "invalid_component_type"}

        sensitivities.append(sensitivity)

    # Validate correlation matrix
    if correlation_matrix is not None:
        if len(correlation_matrix) != n:
            return {"valid": False, "reason": "invalid_correlation_shape"}
        for row in correlation_matrix:
            if len(row) != n:
                return {"valid": False, "reason": "invalid_correlation_shape"}

        # Check symmetry
        for i in range(n):
            for j in range(i + 1, n):
                if abs(correlation_matrix[i][j] - correlation_matrix[j][i]) > 1e-10:
                    return {"valid": False, "reason": "invalid_correlation_matrix"}

        # Check diagonal entries
        for i in range(n):
            if abs(correlation_matrix[i][i] - 1) > 1e-10:
                return {"valid": False, "reason": "invalid_correlation_diagonal"}

        # Check all entries are within [-1, 1]
        for i in range(n):
            for j in range(n):
                val = correlation_matrix[i][j]
                if val < -1 - 1e-10 or val > 1 + 1e-10:
                    return {"valid": False, "reason": "invalid_correlation_matrix"}

        # Check for positive semi-definite
        try:
            corr_np = np.array(correlation_matrix, dtype=np.float64)
            eigenvalues = np.linalg.eigvals(corr_np)
            for eig in eigenvalues:
                if eig < -1e-10:
                    return {"valid": False, "reason": "non_psd_correlation_matrix"}
        except:
            return {"valid": False, "reason": "invalid_correlation_matrix"}

    # Calculate combined uncertainty (with or without correlation)
    uc_squared = Decimal(0)
    for i in range(n):
        sensitivity_i = sensitivities[i]
        u_i = u_i_list[i]
        term = sensitivity_i ** 2 * u_i ** 2
        uc_squared += term

    if correlation_matrix is not None:
        for i in range(n):
            for j in range(i + 1, n):
                sensitivity_i = sensitivities[i]
                sensitivity_j = sensitivities[j]
                rho_ij = Decimal(correlation_matrix[i][j])
                u_i = u_i_list[i]
                u_j = u_i_list[j]
                term = 2 * sensitivity_i * sensitivity_j * rho_ij * u_i * u_j
                uc_squared += term

    if uc_squared < 0:
        return {"valid": False, "reason": "negative_propagated_variance"}

    uc = uc_squared ** Decimal(0.5)

    # Handle scaling (coverage factor)
    if coverage_factor is None:
        return {"valid": False, "reason": "invalid_coverage_factor"}

    try:
        coverage_factor = Decimal(str(coverage_factor))
    except InvalidOperation:
        return {"valid": False, "reason": "invalid_coverage_factor"}

    if coverage_factor <= 0:
        return {"valid": False, "reason": "invalid_coverage_factor"}

    final_uncertainty = uc * coverage_factor

    # Return the structured result
    return {
        "valid": True,
        "uncertainty": float(final_uncertainty),
        "components": [
            {
                "sensitivity": float(sensitivities[i]),
                "u": float(u_i_list[i])
            }
            for i in range(n)
        ]
    }
